'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex128 = require( '@stdlib/complex-float64-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var pkg = require( './../package.json' ).name;
var real = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var re;
	var i;

	values = [
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		re = real( values[ i%values.length ] );
		if ( isnan( re ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( re ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-real/benchmark/benchmark.js","time":{"start":1783262173346,"end":1783262173350}},"id":"prt_f32b557be001vjT5F2GtHj9t7b","sessionID":"ses_0cd4b0d2fffeNWackAXsgAWW0Z","messageID":"msg_f32b54425001dw4bQngP9Z1kXf"}}

